import Foundation
import Testing

@testable import FieldDesign

/// IOS-12a (PC-D6 A; DESIGN.md §2.10) — the spark face's DNA golden, in this bundle: what the desktop's vendored engine
/// (`packages/design-kit/src/spark-face/vendor/sparks.js`) deals for 24 seeds, and the twelve palettes a spark draws
/// from. It is generated by `packages/design-kit/scripts/spark-dna-golden.mjs`, held to the engine by field-app's
/// `spark-face.test.tsx`, and copied in byte for byte (`pnpm check:ios-fixtures`).
/// IOS-12b — the phone's own deal, `SparkEngine`, is held to it row for row: the DNA, the star's points and the eyes
/// for every seed, and the palettes. The deal is the engine's arithmetic in the engine's order, so it is the same
/// IEEE-754 doubles; the tolerance below is only for the JSON round trip of the golden's shortest-form numbers.
@Suite("the spark face's DNA golden is the desktop engine's")
struct SparkDnaGoldenTests {
  struct Golden: Decodable {
    struct Row: Decodable {
      struct DNA: Decodable {
        struct Body: Decodable {
          let n: Int
          let core, reach, hw, tip, k, jitter, rot: Double
          let hero: Int
          let heroLen, heroBend: Double
          let stub: Int
        }
        struct Eyes: Decodable {
          let gap, y, w, h: Double
          let shape: Int
          let tilt: Double
        }
        let seed: UInt32
        let palette: Int
        let body: Body
        let eyes: Eyes
      }
      struct Body: Decodable {
        let n: Int
        let core, k, tip: Double
        let pts: [[Double]]
      }
      struct Eyes: Decodable {
        let gap, y, w, h: Double
        let shape: Int
        let tilt, lidY, lidAng: Double
        let look: [Double]
        let mouthY: Double
      }
      let seed: UInt32
      let dna: DNA
      let body: Body
      let eyes: Eyes
    }
    struct Palette: Decodable {
      let name: String
      let c: [String]
      let deep: [String]
    }
    let seeds: [Row]
    let palettes: [Palette]
  }

  private func golden() throws -> Golden {
    let url = try #require(
      Bundle.module.url(forResource: "spark-dna.golden", withExtension: "json", subdirectory: "Fixtures"))
    return try JSONDecoder().decode(Golden.self, from: Data(contentsOf: url))
  }

  /// Equal to the golden's printed number: the deal is exact, the JSON round trip is the only slack.
  private func near(_ a: Double, _ b: Double) -> Bool { abs(a - b) <= 1e-12 * max(1, abs(b)) }

  @Test("24 seeds, each dealt from its own seed, across the 32 bits")
  func seeds() throws {
    let rows = try golden().seeds
    #expect(rows.count == 24)
    #expect(rows.allSatisfy { $0.dna.seed == $0.seed })
    #expect(rows.contains { $0.seed == 0 } && rows.contains { $0.seed == UInt32.max })
    #expect(rows.allSatisfy { (0..<12).contains($0.dna.palette) })
  }

  @Test("the twelve palettes, each eight colours and a backdrop of two, as hex")
  func palettes() throws {
    let palettes = try golden().palettes
    #expect(palettes.count == 12)
    // `#rrggbb`, lowercase, as the engine writes them
    let isHex = { (colour: String) -> Bool in
      let bytes = Array(colour.utf8)
      return bytes.count == 7 && bytes[0] == UInt8(ascii: "#")
        && bytes.dropFirst().allSatisfy { (0x30...0x39).contains($0) || (0x61...0x66).contains($0) }
    }
    for palette in palettes {
      #expect(!palette.name.isEmpty)
      #expect(palette.c.count == 8, "\(palette.name)")
      #expect(palette.deep.count == 2, "\(palette.name)")
      #expect((palette.c + palette.deep).allSatisfy(isHex), "\(palette.name)")
    }
  }

  // MARK: - IOS-12b: the phone deals the desktop's DNA

  @Test("the phone's agentDNA is the engine's, trait for trait, for every seed")
  func agentDNA() throws {
    for row in try golden().seeds {
      let dna = SparkEngine.agentDNA(row.seed)
      let want = row.dna
      #expect(dna.seed == want.seed && dna.palette == want.palette, "seed \(row.seed)")
      let b = dna.body
      let wb = want.body
      #expect(b.n == wb.n && b.hero == wb.hero && b.stub == wb.stub, "seed \(row.seed) body counts")
      let pairs: [(Double, Double)] = [
        (b.core, wb.core), (b.reach, wb.reach), (b.hw, wb.hw), (b.tip, wb.tip), (b.k, wb.k),
        (b.jitter, wb.jitter), (b.rot, wb.rot), (b.heroLen, wb.heroLen), (b.heroBend, wb.heroBend),
        (dna.eyes.gap, want.eyes.gap), (dna.eyes.y, want.eyes.y), (dna.eyes.w, want.eyes.w),
        (dna.eyes.h, want.eyes.h), (dna.eyes.tilt, want.eyes.tilt),
      ]
      #expect(pairs.allSatisfy { near($0.0, $0.1) }, "seed \(row.seed) traits")
      #expect(dna.eyes.shape == want.eyes.shape, "seed \(row.seed) eye shape")
    }
  }

  @Test("the star the phone builds from that DNA is the engine's, point for point")
  func makeBody() throws {
    for row in try golden().seeds {
      let body = SparkEngine.makeBody(row.seed, SparkEngine.agentDNA(row.seed).body)
      let want = row.body
      #expect(body.n == want.n && body.points.count == want.pts.count, "seed \(row.seed)")
      #expect(near(body.core, want.core) && near(body.k, want.k) && near(body.tip, want.tip), "seed \(row.seed)")
      for (point, wanted) in zip(body.points, want.pts) {
        #expect(wanted.count == 4)
        #expect(
          near(point.angle, wanted[0]) && near(point.length, wanted[1]) && near(point.halfWidth, wanted[2])
            && near(point.bend, wanted[3]),
          "seed \(row.seed)")
      }
    }
  }

  @Test("the eyes the phone builds from that DNA are the engine's")
  func makeEyes() throws {
    for row in try golden().seeds {
      let eyes = SparkEngine.makeEyes(row.seed, SparkEngine.agentDNA(row.seed).eyes)
      let want = row.eyes
      #expect(eyes.shape == want.shape, "seed \(row.seed)")
      let pairs: [(Double, Double)] = [
        (eyes.gap, want.gap), (eyes.y, want.y), (eyes.w, want.w), (eyes.h, want.h), (eyes.tilt, want.tilt),
        (eyes.lidY, want.lidY), (eyes.lidAng, want.lidAng), (eyes.lookX, want.look[0]), (eyes.lookY, want.look[1]),
        (eyes.mouthY, want.mouthY),
      ]
      #expect(pairs.allSatisfy { near($0.0, $0.1) }, "seed \(row.seed)")
    }
  }

  @Test("the phone's twelve palettes are the engine's, colour for colour")
  func phonePalettes() throws {
    let want = try golden().palettes
    #expect(SparkEngine.palettes.count == want.count)
    for (palette, wanted) in zip(SparkEngine.palettes, want) {
      #expect(palette.name == wanted.name)
      #expect(palette.c == wanted.c, "\(wanted.name)")
      #expect(palette.deep == wanted.deep, "\(wanted.name)")
    }
  }
}
